<!doctype html>
<html lang="id">
<head>
    <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
    <title>Titip Kilat API</title>
    <style>body{margin:0;background:#fff;font-family:Inter,system-ui,sans-serif;color:#1E293B}.wrap{max-width:900px;margin:0 auto;padding:72px 24px}.brand{color:#E53935;font-size:18px;font-weight:800;letter-spacing:.04em}.hero{margin-top:56px;background:linear-gradient(135deg,#E53935,#FB8C00);border-radius:24px;padding:48px;color:#fff;box-shadow:0 18px 50px #e5393530}h1{font-size:clamp(38px,7vw,72px);margin:8px 0 16px}p{font-size:18px;line-height:1.6}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-top:28px}.card{border:1px solid #e2e8f0;border-radius:16px;padding:22px}.card h3{margin-top:0;color:#E53935}.pill{display:inline-block;background:#fff;color:#E53935;border-radius:999px;padding:8px 14px;font-weight:700}.muted{color:#64748b}</style>
</head>
<body><main class="wrap"><div class="brand">TITIP KILAT</div><section class="hero"><span class="pill">Backend API online</span><h1>Titip jadi kilat.</h1><p>Platform terpadu untuk jasa titip antar warga dan perjalanan internasional.</p></section><div class="grid"><div class="card"><h3>REST API</h3><p class="muted">Authentication, orders, wallet, trips, dan dashboard role tersedia.</p></div><div class="card"><h3>Mobile-ready</h3><p class="muted">Client Flutter Web berjalan di port 8080 dan siap dikompilasi ke mobile.</p></div><div class="card"><h3>API Base URL</h3><p class="muted"><code>{{ url('/api') }}</code></p></div></div></main></body>
</html>
